import { cn } from '@/registry/ndeko/lib/utils';
import {
  Avatar,
  AvatarFallback,
  AvatarImage,
} from '@/registry/ndeko/ui/avatar';

import { PRESENCE_META, type Member } from './people';

const SIZE_CLASS = {
  sm: { avatar: 'size-7 text-[10px]', badge: 'size-3.5', glyph: 'size-2' },
  md: { avatar: 'size-9 text-xs', badge: 'size-4', glyph: 'size-2.5' },
  lg: { avatar: 'size-12 text-sm', badge: 'size-5', glyph: 'size-3' },
} as const;

type PresenceAvatarProps = {
  member: Member;
  size?: keyof typeof SIZE_CLASS;
  /** The colour behind the badge's cut-out: the surface the avatar sits on. */
  surfaceClassName?: string;
  className?: string;
};

/** A person's face with their presence as a small glyph on its corner, read out after the name. */
export function PresenceAvatar({
  member,
  size = 'md',
  surfaceClassName = 'bg-card',
  className,
}: PresenceAvatarProps) {
  const presence = PRESENCE_META[member.presence];
  const Glyph = presence.glyph;
  const badgeStyle = { '--chip': presence.color } as React.CSSProperties;
  const sizes = SIZE_CLASS[size];

  return (
    <span className={cn('relative inline-flex shrink-0', className)}>
      <Avatar className={sizes.avatar}>
        {member.avatar && <AvatarImage src={member.avatar} alt='' />}
        <AvatarFallback>{member.initials}</AvatarFallback>
      </Avatar>
      <span
        aria-hidden='true'
        className={cn(
          'absolute -end-0.5 -bottom-0.5 flex rounded-full p-px',
          surfaceClassName
        )}
      >
        <span
          style={badgeStyle}
          className={cn(
            'chip-3d flex items-center justify-center rounded-full',
            sizes.badge
          )}
        >
          <Glyph className={sizes.glyph} strokeWidth={2.75} />
        </span>
      </span>
      <span className='sr-only'>{presence.label}</span>
    </span>
  );
}

'use client';

import {
  AnimatePresence,
  motion,
  useReducedMotion,
  type Transition,
  type Variants,
} from 'motion/react';

import { cn } from '@/registry/ndeko/lib/utils';

const SWAP_TRANSITION: Transition = { duration: 0.15, ease: [0.2, 0, 0, 1] };

const SWAP_VARIANTS: Variants = {
  enter: { opacity: 0, scale: 0.6, filter: 'blur(2px)' },
  visible: { opacity: 1, scale: 1, filter: 'blur(0px)' },
  exit: { opacity: 0, scale: 0.6, filter: 'blur(2px)' },
};

const FADE_VARIANTS: Variants = {
  enter: { opacity: 0 },
  visible: { opacity: 1 },
  exit: { opacity: 0 },
};

function variantsOf(shouldReduceMotion: boolean | null) {
  if (shouldReduceMotion) {
    return FADE_VARIANTS;
  }
  return SWAP_VARIANTS;
}

type SwapProps = {
  /** Changes when the content becomes another one. */
  swapKey: string;
  className?: string;
  children: React.ReactNode;
};

/** An icon that becomes another: the old one shrinks out of focus while the new one settles. */
export function Swap({ swapKey, className, children }: SwapProps) {
  const shouldReduceMotion = useReducedMotion();

  return (
    <AnimatePresence mode='popLayout' initial={false}>
      <motion.span
        key={swapKey}
        variants={variantsOf(shouldReduceMotion)}
        initial='enter'
        animate='visible'
        exit='exit'
        transition={SWAP_TRANSITION}
        className={cn('flex', className)}
      >
        {children}
      </motion.span>
    </AnimatePresence>
  );
}

